h2 { margin-top: 32px; font-size: 1.2rem; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
.input-line { display: flex; gap: 12px; }
input { min-width: 0; flex: 1; border: 1px solid #788698; border-radius: 6px; padding: 10px; font: inherit; }
button { background: #2455b3; color: white; border: 0; border-radius: 6px; padding: 11px 16px; font: inherit; cursor: pointer; }
