.projects form { flex-shrink: 0; }
.filter-form { margin-top: 24px; }
select { padding: 10px; border: 1px solid #788698; border-radius: 6px; background: white; font: inherit; }
.tasks { padding: 0; list-style: none; }
.tasks li { padding: 16px 0; border-bottom: 1px solid #dce2eb; }
.task-label { display: flex; align-items: center; gap: 12px; margin: 0; font-weight: 400; }
.task-label input { flex: none; width: 20px; height: 20px; }
.task-label span { overflow-wrap: anywhere; min-width: 0; }
.error { color: #a21d24; font-weight: 600; }
@media (max-width: 600px) { main { margin: 16px; padding: 24px; } .input-line { flex-direction: column; } }

